cat > /app/output/gen.py <<'PY'
"""Original camera/depth controller, using only the robot service API.
Commands are recorded alongside observations. No resets or hidden scene state.
"""
import json, pathlib, sys, traceback, time
import numpy as np
from scipy.spatial.transform import Rotation as R
from scipy.optimize import least_squares
from rcb_client import Robot
ROOT=pathlib.Path('/app/runs');ROOT.mkdir(exist_ok=True)

def trans(p=(0,0,0),r=(0,0,0)):
 T=np.eye(4);T[:3,:3]=R.from_euler('xyz',r).as_matrix();T[:3,3]=p;return T
origins=[trans((0,0,.333)),trans(r=(-np.pi/2,0,0)),trans((0,-.316,0),(np.pi/2,0,0)),trans((.0825,0,0),(np.pi/2,0,0)),trans((-.0825,.384,0),(-np.pi/2,0,0)),trans(r=(np.pi/2,0,0)),trans((.088,0,0),(np.pi/2,0,0))]
def fk(q):
 T=np.eye(4)
 for o,a in zip(origins,q):T=T@o@trans(r=(0,0,a))
 return T@trans((0,0,.107),r=(0,0,-np.pi/4))@trans((0,0,.097))

class Controller:
 def __init__(self):
  self.r=Robot();self.spec=self.r.spec();self.cams=list(self.spec['cameras']);self.n=0;self.cal=[];self.B=None
  self.obs=self.r.get_obs(include_depth=True,video='none');self.save('connect');self.update()
 def update(self):
  m=self.obs.meta['proprio'];self.p=dict(zip(m['layout'],m['now']));self.q=np.array([self.p[f'robot0_joint{i}_pos'] for i in range(1,8)]);self.eef=np.array([self.p['eef_right_'+i] for i in 'xyz'])
  self.cmd=np.array([self.p['cmd_arm_joint'+str(i)] for i in range(1,8)]+[self.p['cmd_grip'],0,0,0,0,-1.])
 def save(self,note):
  self.n+=1;path=ROOT/f'{self.n:03d}_{note}';self.obs.save(path);self.path=path
  (ROOT/'latest.json').write_text(json.dumps({'path':str(path),'eef':self.obs.meta['proprio']['now'][26:29]}))
 def report(self):
  print(json.dumps({'path':str(self.path),'eef':self.eef.tolist(),'q':self.q.tolist(),'fingers':[self.p[x] for x in ['gripper0_right_finger_joint1_pos','gripper0_right_finger_joint2_pos']],'time_left':self.obs.meta['time_left_s'],'base':[self.p[x] for x in self.spec['proprio_layout'][:4]]}),flush=True)
 def observe(self,note='obs'):
  self.obs=self.r.get_obs(include_depth=True,video='none');self.update();self.save(note);self.report()
 def run(self,A,note):
  with (ROOT/'commands.jsonl').open('a') as f:f.write(json.dumps({'note':note,'actions':np.asarray(A).tolist()})+'\n')
  self.obs=self.r.submit('joint_position',A,cameras=self.cams,include_depth=True,video='none',note=note);self.update();self.save(note);self.report()
 def joints(self,q,seconds=2,grip=None,note='joints'):
  q=np.array(q);a=self.cmd.copy();a[:7]=q
  if grip is not None:a[7]=grip
  n=max(1,int(seconds/.05));A=np.linspace(self.cmd,a,n);A[:,8:12]=0;A[:,12]=-1
  self.run(np.vstack([A,np.tile(a,(10,1))]),note)
 def calibrate(self):
  self.cal.append((fk(self.q)[:3,3],self.eef.copy()))
  if len(self.cal)>=3:
   X=np.array([x for x,y in self.cal]);Y=np.array([y for x,y in self.cal]);xm=X.mean(0);ym=Y.mean(0);u,s,v=np.linalg.svd((X-xm).T@(Y-ym));rr=v.T@u.T
   if np.linalg.det(rr)<0:v[-1]*=-1;rr=v.T@u.T
   self.B=np.eye(4);self.B[:3,:3]=rr;self.B[:3,3]=ym-rr@xm
   print('BASE',self.B.tolist(),'residual',np.linalg.norm(X@rr.T+self.B[:3,3]-Y,axis=1).tolist(),flush=True)
  else:print('CAL',self.cal[-1][0].tolist(),self.eef.tolist(),flush=True)
 def move(self,pos,rotation=None,seconds=2,grip=None,note='move'):
  if self.B is None:raise ValueError('Calibrate first')
  target=np.asarray(pos)
  rot=np.diag([1,-1,-1]) if rotation is None else R.from_euler('xyz',rotation).as_matrix()
  def fun(q):
   t=self.B@fk(q);return np.r_[5*(t[:3,3]-target),R.from_matrix(rot@t[:3,:3].T).as_rotvec(),.005*(q-self.q)]
  bounds=([-2.89,-1.76,-2.89,-3.06,-2.89,-.01,-2.89],[2.89,1.76,2.89,-.07,2.89,3.75,2.89])
  sol=least_squares(fun,np.clip(self.q,np.array(bounds[0])+1e-4,np.array(bounds[1])-1e-4),bounds=bounds,max_nfev=300)
  t=self.B@fk(sol.x);print('IK',sol.x.tolist(),'pred',t[:3,3].tolist(),'err',np.linalg.norm(t[:3,3]-target),flush=True)
  if np.linalg.norm(t[:3,3]-target)>.025:raise ValueError('Unreachable goal')
  self.joints(sol.x,seconds,grip,note)
 def execute(self,c):
  op=c.pop('op');getattr(self,op)(**c)

if __name__=='__main__':
 c=Controller();c.report()
 for line in sys.stdin:
  try:c.execute(json.loads(line))
  except Exception:traceback.print_exc()
